module logic;
use model {Summary,Event};
use util {reverse};
record Cursor<T> { pending:List<T>, balance:I64, rejected:I64, peak:I64, locked:Bool, audit:List<I64> }
fn run(events:List<Event>,initial:I64)->Summary {
 let final=fold(i in List::length(events),state:Cursor<Event>=Cursor {pending:events,balance:initial,rejected:0,peak:initial,locked:false,audit:List::empty<I64>()}) {
  let event=List::head(state.pending);
  let rest=List::tail(state.pending);
  let next=match event {
   Credit(amount)=>(if amount<0 || amount>1000000 {Cursor {pending:rest,balance:state.balance,rejected:state.rejected+1,peak:state.peak,locked:state.locked,audit:List::prepend(state.balance,state.audit)}} else {let changed=state.balance+amount; Cursor {pending:rest,balance:changed,rejected:state.rejected,peak:if changed>state.peak {changed} else {state.peak},locked:state.locked,audit:List::prepend(changed,state.audit)}}),
   Debit(amount)=>(if amount<0 || amount>1000000 || state.locked || amount>state.balance {Cursor {pending:rest,balance:state.balance,rejected:state.rejected+1,peak:state.peak,locked:state.locked,audit:List::prepend(state.balance,state.audit)}} else {let changed=state.balance-amount; Cursor {pending:rest,balance:changed,rejected:state.rejected,peak:if changed>state.peak {changed} else {state.peak},locked:state.locked,audit:List::prepend(changed,state.audit)}}),
   Lock=>(Cursor {pending:rest,balance:state.balance,rejected:state.rejected,peak:state.peak,locked:true,audit:List::prepend(state.balance,state.audit)}),
   Unlock=>(Cursor {pending:rest,balance:state.balance,rejected:state.rejected,peak:state.peak,locked:false,audit:List::prepend(state.balance,state.audit)})
  };
  next
 };
 Summary {balance:final.balance,rejected:final.rejected,peak:final.peak,audit:reverse(final.audit)}
}

